from pathlib import Path
import json,csv
P=Path(__file__).resolve().parent;e=json.loads((P/'edits.json').read_text());n=json.loads((P/'notes.json').read_text())
def p(k,t):e[f'A0566-B{k:04d}']=t
p(2,'史洛斯是一种外形近似人类的异形，躯体覆盖着数百条半融为一体的蛆状蠕虫，表面裹有黏稠的黏液。只有最严重的创伤才能伤及它们。')
p(7,'史洛斯被认为古老得难以想象，很可能在人类到来之前，便已生活在卡利西斯星区。已知活动大多集中在哈冼录深渊周边，那是一片遍布诅咒空域与死亡恒星的地区。不过，它们真正的母星尚不为人知，也可能位于深渊之外。帝国对其起源所知甚少，行商浪人与异形学者则推测：如果它们拥有帝国，其疆域应在星系旋转后方的光环群星之外、极为遥远的地方。人类何时首次接触史洛斯，已无从确定；部分资料称，早在纷争时代，人类便在后来帝国疆域的边缘遭遇过它们。银河中人类数量众多，因而成为史洛斯最钟爱的猎物。即便如此，它们似乎仍乐于依靠渗透与人类代理人，实施那些难以理解的计划。')
p(9,'Intendant Recusant, a former Slaugth leader in charge of portions of the Amaranthine Syndicate for decades 异见监督者：这名史洛斯首领曾掌管不凋花企业联合的部分业务，长达数十年')
p(11,'与史洛斯的许多遭遇有着相似的经过：幽暗的黑色舰船进入帝国空域，袭击孤立的前哨与航运线路。受害者或只留下残缺的尸体，或消失得无影无踪。还有些时候，史洛斯会向叛离帝国的人类提供邪恶技术，换取奴隶。在哈冼录深渊边缘的帝国世界上，人们常把它们称为“行走的蠕虫”——从深渊中爬出的噩梦，杀戮生者、吞食死者。然而，帝国高层多半将这些传闻视作虚构的怪谈。')
p(13,'审判庭却知道，史洛斯确实存在。封存的审判庭档案称，数千年来，朦胧星域的若干边境世界遭人蓄意挑起内战，目的是让史洛斯趁虚而入，吞食居民。但即便是知晓其存在的人，也无法解释这些诡秘计划的最终目的；他们只知道，史洛斯似乎都在采用同一种手段。')
p(15,'事实上，史洛斯避免与帝国正面交战，是因为人类在数量上远远超过它们。单个人类固然不是史洛斯的对手，但一旦激怒帝国、引发全面战争，人类的数量优势便足以使史洛斯迅速败北。即便如此，已有迹象表明，它们正为日后公然进攻卡利西斯星区做准备。')
p(17,'在“守夜星清洗”中，风暴守望者星际战士战团曾在守夜星与史洛斯及其战士构造体交战。战斗由一连串血腥的近距离交火组成，战场过于狭窄，重型装甲单位无法展开。风暴守望者原本谨慎而有序地推进，史洛斯却擅长挑衅、诱使阿斯塔特放弃稳健的战术。战事持续，伤亡攀升，战团士气也受到严峻考验。最终，风暴守望者付出沉重代价，才将史洛斯的威胁从守夜星清除。')
p(19,'为满足无休止的饥饿，史洛斯将目光投向卡利西斯星区，通过煽动内战、制造混乱，逐步瓦解当地秩序。不凋花企业联合尚是新兴贸易垄断集团时，它们便开始渗透，最终将其完全控制。这项计划可能要经历数代人才能见效，却简单而巧妙：只需利用人类固有的贪婪。史洛斯给予人类技术、财富和奇巧玩物，诱使他们为争夺这些东西自相残杀。等计划推进到一定阶段，它们便准备渗透帝国主要的犯罪、政治与经济组织，国教和内政部很可能成为目标。待时机成熟，整个星区将从内部崩溃，史洛斯便可席卷而来，任意宰割。')
p(21,'许多人把史洛斯视为可怕的神话，认为它们不过是疯癫行商浪人在星际航行中编出的怪谈。审判庭知道这一威胁真实存在，却已封锁相关消息数千年。然而，各审判庭仍不知道，不凋花企业联合如今已受史洛斯控制。史洛斯在卡利西斯星区的活动也愈发频繁，代理人网络遍布各地。它们内部并非毫无分歧：一名被称为“异见监督者”的史洛斯，因沉迷于无法满足的饥饿而脱离上级，自立派系。如今，它率领史洛斯渗透者、一支构造体队伍，以及不凋花企业联合中的一批人类，追逐自己的目标。')
p(24,'史洛斯又被称为“蛆虫人”“食梦者”和“腐尸领主”，其身体与心智都与人类迥异。它们近似人形，身高可达约三米；躯体由数百条不断蠕动的蛆状蠕虫构成，裹着黏稠、会使组织坏死的黏液。这种结构让它们能随意伸展、重塑身体，以令人作呕的无骨姿态流动，伤口也会迅速再生。衰老、疾病与毒物都无法伤害史洛斯，只有最严重的创伤才对其构成威胁。它们的心智冷酷凶残，在灵能感知中如同一片虚无，却又充满对尸体的无边渴望。它们的身体组织能够分泌致坏死液体，其中含有噬肉细菌与分子酸，足以溶解血肉，甚至蚀穿金属。诡异的技术与骇人的外表，使许多人误以为它们是恶魔。史洛斯也会掩盖真貌，伪装成人类，混迹于人群之中。')
p(26,'史洛斯不受衰老所限，耐心漫长，其心理对人类而言难以理解。不过，它们至少有一种容易辨认的欲望：成瘾般的饥饿。它们尤其渴求其他智慧生物的尸肉，最迷恋吞食脑组织，从中获得类似吸食毒品的快感。有人认为，它们还能借此攫取受害者的记忆与知识，而这种说法确有其事。因此，腐烂的脑组织虽然能带来更强烈的快感，若是为了获取情报，史洛斯仍会选择较新鲜的大脑。除非不断强化、反复调用，或以外部方式记录，这些窃来的记忆会在数周内消退。')
p(28,'傲慢的史洛斯并不将克制视为美德，也不认为对进食的痴迷会妨碍思考。它们极其聪明，生命力顽强，而且依人类的标准而言，邪恶透顶。')
p(30,'已知史洛斯中有一类称作“首席”，担任不凋花企业联合的监管者；但它们究竟是统治阶层，还是某个特定的密谋集团，尚不得而知。“破坏者”能够伪装成人类，将钻研毁灭之道置于一切追求之上。它们也能恢复真貌，化作一团噩梦般蠕动的白色虫体。另一个已知职衔是“监督者”，负责领导史洛斯的实地行动。')
p(32,'史洛斯与大远征期间凶残的冉丹之间，存在某种联系。在冉丹灭绝战争中，人们曾发现它们尾随冉丹行动，收集死者与幸存者，用于不可告人的骇人目的。资料中也曾以“史洛斯杀戮心智”称呼冉丹。')
p(35,'史洛斯在生物机械技术与基本物理学方面的造诣，超过人类，甚至可能凌驾于灵族之上。它们最神秘的能力之一，是无需借助亚空间，便能横渡星际。许多设备实为培育或强化而成的半生命机械，让血肉与金属共生、协同运作。不明就里的人，很容易将这些武器与造物误认为亚空间巫术的产物。凭借对生物科学精准而可怕的掌握，史洛斯能够直接培育出整支军队，而无须训练士兵。它们还会改造各种构造体，使其担任卫兵、间谍，乃至劳工。')
p(39,'需要隐藏行踪、遮掩骇人真貌时，史洛斯会披上层层长袍，以及被称为“寿衣斗篷”的罩衣。这种织物能够吸收、折射光线，似乎有生命般扭动，让穿戴者从远处看起来，不过是身形畸曲的人类。')
p(41,'“寿衣护甲”则是另一种褴褛斗篷。它能产生奇异效果，干扰旁人的感知，使穿戴者几乎从视线中消失。')
p(43,'已知史洛斯武器包括“坏死权杖”：外表如遭腐蚀，闪烁病态的光芒，开火时射出弧状能量，伴随诡异的呜咽声。它既是威力强大的远程武器，也能用于近战。另有一种原理鲜为人知的“坏死光束”，装备于突击构造体，能将目标化为尘埃。监督者还持有象征其地位的“坏死长枪”，长刃由旋绕、色泽病态的能量丝构成。只需一道指令，长枪便能射出毁灭性的能量束，击毁战斗坦克。')
p(45,'史洛斯的生物机械构造体外形各异，却都令人类作呕。多数“奴仆”呈不对称的悬浮柱状，由斑驳、宛如真菌的血肉构成，表面遍布搏动的血管、交织的金属线网，以及凸起的晶体。它们的头部是一簇摇曳的叶状感官组织，必要时，躯体还能伸出骨架般的钳肢。')
p(47,'“收割者”构造体像一团载具大小、没有固定形状的湿润血肉，表面不断起伏，无声地悬浮在地面上方。它以近乎机械的执着，永不疲倦地寻找智慧生物，为主人搜集食物。发现猎物后，收割者便用末端带有金属钳的触须，将其拖进七鳃鳗般的口器。吞食过程中，猎物头部会被分离，存入构造体背部的半透明囊袋，将脑组织完好保存，留待史洛斯享用。')
p(49,'战士奴仆构造体则是专为战斗培育的生物机械造物。它们由苍白的椭圆形菌状血肉构成，内部布满紫色血管与金属网架，依靠三条蜘蛛般、形似骨架的腿移动。上半身有粗短的管状结构，其中伸出大量触须，环绕着布满尖牙的辐射状巨口。每根触须都异常有力，还能伸展为锋利的骨刃。除触须外，这些战士构造体体内还嵌有光束武器，可发射坏死光束，在数秒内将一名人类分解。')
p(51,'史洛斯战舰火力极其强大，甚至能在短时间内重创荣光女王级战列舰。')
n.update({'A0566-B0007':'Trailing 为银河方位，按星系旋转后方解释，不误读恒星实体尾部；纷争时代早于帝国，Imperial space 在此按后来帝国疆域理解。Hazeroth Abyss 暂沿本稿哈冼录深渊，待官方核对。','A0566-B0015':'原译代词导致败者颠倒；原文明确人类数量占优，全面战争中会迅速失败的是史洛斯。','A0566-B0017':'Vigil 在此为行星守夜星，区别静默修女警戒团与红蝎空间站警戒堡。','A0566-B0019':'Adeptus Administratum 统一内政部；贸易组织沿用本稿不凋花企业联合。','A0566-B0021':'Holy Ordos 指各审判庭，不是神圣修会；英文 Amarantine 为同篇 Amaranthine 的异拼。','A0566-B0024':'psychic voids 指灵能层面的空白或虚无，不是精神空虚；保留所给英文证据范围，不额外断言具体基因起源。','A0566-B0026':'cranial matter 由后文 brain matter 明确为脑组织，原译颅骨错误；sentient beings 为智慧生物，不是佛教有情众生。','A0566-B0030':'英文 writing white forms 疑为 writhing white forms 的笔误，按前后文译为蠕动白色虫体。Destructor 是史洛斯成员类别，不机械套用其他阵营兵种官译。','A0566-B0032':'follow in the wake of the Rangdan 指尾随冉丹，而非尾随大屠杀；联系程度保持原文不确定性。','A0566-B0035':'biomechanical 为生物机械，不是生物力学；grow armies 指培育造物军队。','A0566-B0043':'weapon of rank 表示职衔地位的标志，不是游戏等级武器；shock-construct 按突击用途理解。','A0566-B0049':'maw 是巨口，原译为胃；militant 指战斗用途，不是政治立场激进。'})
rows=list(csv.DictReader((P/'terms.tsv').open(),delimiter='\t'));cols=list(rows[0]);by={r[cols[0]].casefold():r for r in rows}
for en,zh in [('Hazeroth Abyss','哈冼录深渊'),('Amaranthine Syndicate','不凋花企业联合'),('Intendant Recusant','异见监督者'),('Cleansing of Vigil','守夜星清洗'),('Principal','首席（史洛斯职衔）'),('Destructor','破坏者（史洛斯类别）'),('Intendent','监督者（史洛斯职衔）'),('Shroud Cloak','寿衣斗篷'),('Shroud Armour','寿衣护甲'),('Necrotic Sceptre','坏死权杖'),('Necrotic Beam','坏死光束'),('Necrotic Lance','坏死长枪'),('Warrior Vassal Construct','战士奴仆构造体'),('Harvest construct','收割者构造体'),('Miss Book','书籍女士')]:
 by.setdefault(en.casefold(),dict(zip(cols,[en,zh,'暂定·官方待核','所给英文底稿','篇0566','依本篇语境定译；同形普通词不套用其他阵营单位。'])))
by['vigil']=dict(zip(cols,['Vigil','警戒团（静默修女编制）／警戒堡（红蝎空间站）／守夜星（行星）','语境定译·官方待核','所给英文底稿','篇0168、0319、0566','三种实体分译；本篇为清洗战发生的行星。']))
with (P/'terms.tsv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=cols,delimiter='\t');w.writeheader();w.writerows(by.values())
for fn,obj in [('edits.json',e),('notes.json',n)]:(P/fn).write_text(json.dumps(obj,ensure_ascii=False,indent=2))
rv=set(json.loads((P/'reviewed.json').read_text()))|{566};(P/'reviewed.json').write_text(json.dumps(sorted(rv)))
print('566 complete',len(e),'edits')
